export const SidecarName='survival-v1.txt';
export const MaxValue=1000000000;
export function wave(n){if(!Number.isInteger(n)||n<1||n>MaxValue)throw Error('invalid wave');return {number:n,count:Math.min(12,3+n),bossSpecies:n%5===0?100+((n/5-1)%10):0,hpBps:Math.min(1000000,10000+(n-1)*1500),attackBps:Math.min(1000000,10000+(n-1)*1000),gold:Math.min(MaxValue,500*n),crystals:1+Math.floor(n/5),elite:n%3===0};}
const empty=()=>({bestWave:0,completions:0,totalKills:0,bestTimeSeconds:0,survivalScore:0,pendingGold:0,pendingCrystals:0,titleUnlocked:false,pendingCash:0,pendingPure:0,pendingAbyssal:0});
export function createLedger(){return {slots:Array.from({length:10},empty)};}
const valid=s=>s&&['bestWave','completions','totalKills','bestTimeSeconds','survivalScore','pendingGold','pendingCrystals','pendingCash','pendingPure','pendingAbyssal'].every(k=>Number.isInteger(s[k])&&s[k]>=0&&s[k]<=MaxValue)&&typeof s.titleUnlocked==='boolean'&&s.titleUnlocked===(s.bestWave>=20);
export function encode(l){if(!l||!Array.isArray(l.slots)||l.slots.length!==10||!l.slots.every(valid))throw Error('invalid survival state');return 'DESTINIA_SURVIVAL_V1\n'+l.slots.map((s,i)=>'slot '+[i,s.bestWave,s.completions,s.totalKills,s.bestTimeSeconds,s.survivalScore,s.pendingGold,s.pendingCrystals,Number(s.titleUnlocked),s.pendingCash,s.pendingPure,s.pendingAbyssal].join(' ')+'\n').join('')+'end\n';}
export function decode(text){if(typeof text!=='string'||text.length>4096)throw Error('oversized survival');const lines=text.split('\n');if(lines.length!==13||lines[0]!=='DESTINIA_SURVIVAL_V1'||lines[11]!=='end'||lines[12]!=='')throw Error('invalid survival text');const l=createLedger();for(let i=0;i<10;i++){const m=/^slot ([0-9]+) ([0-9]+) ([0-9]+) ([0-9]+) ([0-9]+) ([0-9]+) ([0-9]+) ([0-9]+) ([01]) ([0-9]+) ([0-9]+) ([0-9]+)$/.exec(lines[i+1]);if(!m||Number(m[1])!==i)throw Error('invalid survival slot');l.slots[i]={bestWave:Number(m[2]),completions:Number(m[3]),totalKills:Number(m[4]),bestTimeSeconds:Number(m[5]),survivalScore:Number(m[6]),pendingGold:Number(m[7]),pendingCrystals:Number(m[8]),titleUnlocked:m[9]==='1',pendingCash:Number(m[10]),pendingPure:Number(m[11]),pendingAbyssal:Number(m[12])};}if(encode(l)!==text)throw Error('invalid survival text');return l;}
const uint=n=>Number.isSafeInteger(n)&&n>=0;
export class Arena {
 constructor(){this.ledger=createLedger();this.lastRun=0;this.abort();}
 start(s,run,mapId=0){if(!Number.isInteger(s)||s<0||s>=10||!uint(run)||run===0||run<=this.lastRun||!uint(mapId)||mapId>4294967295)return false;this.abort();this.slot=s;this.runId=this.lastRun=run;this.arenaMap=mapId;this.highestInstance=0;this.runElapsedMs=0;this.active=true;this.currentWave=1;this.remaining=wave(1).count;return true;}
 tick(ms,paused=false){if(!this.active||paused||!Number.isSafeInteger(ms)||ms<0)return;this.runElapsedMs=Math.min(this.runElapsedMs+ms,MaxValue*1000);const s=this.ledger.slots[this.slot];s.bestTimeSeconds=Math.max(s.bestTimeSeconds,Math.floor(this.runElapsedMs/1000));s.survivalScore=Math.max(s.survivalScore,Math.min(MaxValue,s.totalKills*100+s.bestWave*500+s.completions*5000+s.bestTimeSeconds*10));}
 registerMonster(id,species){if(!this.active||this.cleared||!uint(id)||!id||id<=this.highestInstance||!uint(species)||species>4294967295||this.members.size>=wave(this.currentWave).count)return false;const w=wave(this.currentWave);if(species>=100){if(!w.bossSpecies||species!==w.bossSpecies||this.bossRegistered)return false;this.bossRegistered=true;}else if(w.bossSpecies&&!this.bossRegistered&&this.members.size+1===w.count)return false;this.members.set(id,{species,dead:false});this.highestInstance=id;return true;}
 observeKill(run,id,mapId=0,slot=-1){if(!this.active||this.cleared||run!==this.runId||mapId!==this.arenaMap||(slot>=0&&slot!==this.slot))return false;const m=this.members.get(id);if(!m||m.dead)return false;m.dead=true;--this.remaining;const s=this.ledger.slots[this.slot];s.totalKills=Math.min(MaxValue,s.totalKills+1);s.survivalScore=Math.min(MaxValue,s.survivalScore+100);if(!this.remaining){const w=wave(this.currentWave);s.bestWave=Math.max(s.bestWave,this.currentWave);s.pendingGold=Math.min(MaxValue,s.pendingGold+w.gold);s.pendingCash=Math.min(MaxValue,s.pendingCash+(this.currentWave%5===0?this.currentWave:1));const key=this.currentWave<=10?'pendingCrystals':this.currentWave<=25?'pendingPure':'pendingAbyssal';s[key]=Math.min(MaxValue,s[key]+w.crystals);s.titleUnlocked=s.bestWave>=20;s.survivalScore=Math.min(MaxValue,s.survivalScore+500);this.cleared=true;if(this.currentWave%50===0){s.completions=Math.min(MaxValue,s.completions+1);s.survivalScore=Math.min(MaxValue,s.survivalScore+5000);}}return true;}
 beginNextWave(){if(!this.active||!this.cleared||this.currentWave>=MaxValue)return false;++this.currentWave;this.remaining=wave(this.currentWave).count;this.members.clear();this.bossRegistered=this.cleared=false;return true;}
 abort(){this.active=false;this.slot=-1;this.runId=0;this.currentWave=this.remaining=0;this.runElapsedMs=0;this.members=new Map();this.bossRegistered=this.cleared=false;}
 takePending(slot){if(!Number.isInteger(slot)||slot<0||slot>=10)return {gold:0,crystals:0,cash:0,pure:0,abyssal:0};const s=this.ledger.slots[slot],r={gold:s.pendingGold,crystals:s.pendingCrystals,cash:s.pendingCash,pure:s.pendingPure,abyssal:s.pendingAbyssal};s.pendingGold=s.pendingCrystals=s.pendingCash=s.pendingPure=s.pendingAbyssal=0;return r;}
}
